    public void GenerateChallenge()
    {
        difficulty = bm.tokenDifficulty;
        switch(difficulty)
        {
            case 0:
                if(Random.Range(0, 2) == 1)
                {
                    correctWord = fiveLetters[Random.Range(0, fiveLetters.Length)];
                } else
                {
                    correctWord = sixLetters[Random.Range(0, sixLetters.Length)];
                }
                break;
            case 1:
                if(Random.Range(0, 2) == 1)
                {
                    correctWord = sevenLetters[Random.Range(0, sevenLetters.Length)];
                } else
                {
                    correctWord = eightLetters[Random.Range(0, eightLetters.Length)];
                }
                break;
            case 2:
                if(Random.Range(0, 2) == 1)
                {
                    correctWord = tenLetters[Random.Range(0, tenLetters.Length)];
                } else
                {
                    correctWord = tenLetters[Random.Range(0, tenLetters.Length)];
                }
                break;
        }
        wordText.text = correctWord;
    }
    public void SubmitWord()
    {
        if(type.text.ToLower() == correctWord)
        {
            type.ActivateInputField();
            type.Select();
            type.text = "";
            bm.WinChallenge();
        } else
        {
            type.ActivateInputField();
            type.Select();
            type.text = "";
            bm.FailChallenge();
            GenerateChallenge();
        }
    }
